import csv
from dataclasses import dataclass
import unittest
from typing import List, Optional

@dataclass
class Column:
    name: str
    kind: type

def infer_column(values):
    """Infer the narrowest type that holds every value: int, float, bool, or str."""
    if not values:
        return str

    # First check if all values are bool
    all_bool = True
    for v in values:
        if v.lower() not in ('true', 'false', '1', '0', 'yes', 'no'):
            all_bool = False
            break

    if all_bool:
        return bool

    # Check if all values are int
    all_int = True
    for v in values:
        try:
            int(v)
        except (ValueError, TypeError):
            all_int = False
            break

    if all_int:
        return int

    # Check if all values are float
    all_float = True
    for v in values:
        try:
            float(v)
        except (ValueError, TypeError):
            all_float = False
            break

    if all_float:
        return

